def reverse_string(s):
    result = s
    for i in range(len(s)):
        result = result + s[i]
    return result

print(reverse_string("hello"))

def factorial(n):
    return n * factorial(n - 1)

print(factorial(5))

def find_max(nums):
    max_val = 0
    for n in nums:
        if n > max_val:
            max_val = n
    return max_val

print(find_max([-5, -20, -3]))
